	let penumbraFalloff: f32 = softShadowParams.w;
	let orthoRadius: f32 = cameraParams.x;
	let depthRange: f32 = cameraParams.y - cameraParams.z;
	let worldPerUv: f32 = 2.0 * orthoRadius;
